// The V8 engine allows us to query memory usage directly in Node
const v8 = require('v8');

// Getting heap statistics directly from the V8 Engine
const stats = v8.getHeapStatistics();

console.log(`Total Heap Size: ${Math.round(stats.total_heap_size / 1024 / 1024)} MB`);
console.log(`Heap Size Limit: ${Math.round(stats.heap_size_limit / 1024 / 1024)} MB`);

// If your app exceeds the Heap Size Limit (usually ~1.5GB by default),
// the V8 engine will crash with an 'Out of Memory' error.
